require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/Upload.php';Auth::requireLogin();$pageTitle='فایل‌های شخصی';$user=Auth::user();
if(isset($_GET['delete'])&&Auth::verifyCsrf($_GET['csrf_token']??'')){ $file=Database::fetch('SELECT * FROM user_files WHERE id=?'.(Auth::isAdmin()?'':' AND user_id=?'), Auth::isAdmin()?[(int)$_GET['delete']]:[(int)$_GET['delete'],$user['id']]); if($file){@unlink(__DIR__.'/..'.$file['file_path']);Database::execute('DELETE FROM user_files WHERE id=?',[$file['id']]);flash('فایل حذف شد.');} redirect('/admin/files.php');}
